#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""最小可用 MCP 服务骨架（stdio + http 双模，零依赖）。"""
import json, sys, os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

TOOLS = {
    "hello": {
        "name": "hello",
        "description": "返回问候语",
        "inputSchema": {
            "type": "object",
            "properties": {"name": {"type": "string", "description": "你的名字"}},
            "required": ["name"],
        },
    }
}


def call_tool(name, args):
    if name == "hello":
        return {"content": [{"type": "text", "text": "hi %s" % args.get("name", "there")}]}
    raise KeyError(name)


def handle(msg):
    mid = msg.get("id")
    method = msg.get("method")
    if method == "initialize":
        return {"jsonrpc": "2.0", "id": mid, "result": {
            "protocolVersion": "2024-11-05",
            "capabilities": {"tools": {"listChanged": False}},
            "serverInfo": {"name": "my-mcp", "version": "1.0.0"},
        }}
    if method == "tools/list":
        return {"jsonrpc": "2.0", "id": mid, "result": {"tools": list(TOOLS.values())}}
    if method == "tools/call":
        p = msg.get("params") or {}
        try:
            return {"jsonrpc": "2.0", "id": mid, "result": call_tool(p.get("name"), p.get("arguments") or {})}
        except KeyError:
            return {"jsonrpc": "2.0", "id": mid,
                    "error": {"code": -32602, "message": "unknown tool"}}
    if method in ("ping",):
        return {"jsonrpc": "2.0", "id": mid, "result": {}}
    if mid is None:
        return None
    return {"jsonrpc": "2.0", "id": mid, "error": {"code": -32601, "message": "method not found"}}


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, obj, code=200):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path.startswith("/healthz"):
            self._send({"ok": True})
        else:
            self._send({"error": "use POST /mcp"}, 405)

    def do_POST(self):
        n = int(self.headers.get("Content-Length") or 0)
        try:
            msg = json.loads(self.rfile.read(n).decode("utf-8"))
        except Exception:
            self._send({"jsonrpc": "2.0", "id": None,
                        "error": {"code": -32700, "message": "parse error"}}, 400)
            return
        out = handle(msg)
        if out is None:
            self._send({}, 202)
        else:
            self._send(out)


def main():
    if "--stdio" in sys.argv:
        for line in sys.stdin:
            line = line.strip()
            if not line:
                continue
            out = handle(json.loads(line))
            if out is not None:
                sys.stdout.write(json.dumps(out, ensure_ascii=False) + "\n")
                sys.stdout.flush()
    else:
        port = int(os.environ.get("MCP_PORT", "9000"))
        ThreadingHTTPServer(("0.0.0.0", port), H).serve_forever()


if __name__ == "__main__":
    main()
